package netdiag

import (
	"strconv"
	"strings"
	"time"

	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewState represents the current state of the netdiag view
type ViewState int

const (
	StateInput   ViewState = iota // Target, port and resolver
	StateRunning                  // The pipeline is walking its stages
	StateResults                  // The checks and their verdicts
	StateDetails                  // One check explained
)

// Tab indices. tabCount is what Tab cycles through, and it is a constant
// rather than a literal because the two places that cycle would otherwise have
// to be found and changed together — which is exactly the kind of pair that
// gets changed once.
const (
	tabDiagnostics = 0
	tabPorts       = 1
	tabInterfaces  = 2
	tabForward     = 3

	tabCount = 4
)

// Form field indices.
//
// There were eleven, seven of them checkboxes selecting which tools to run.
// They asked the user to configure something the pipeline derives: the checks
// follow from the target and from what has already failed, so a question that
// was never worth asking is no longer asked.
const (
	fieldTarget    = 0
	fieldPort      = 1
	fieldDNSServer = 2
	fieldButton    = 3
	fieldCount     = 4
)

// problemsToken filters the table down to what is not settled.
//
// One token rather than one per verdict: a run produces about ten rows, and
// four cumulative filters over ten rows is machinery nobody needs. What a
// reader wants is to drop the settled rows and see what went wrong.
const problemsToken = "REDACTED"

// stageDoneMsg carries the results after one stage of the pipeline.
//
// The accumulated Results travels *in the message* rather than being mutated in
// place: the model holds the previous value while the next stage runs on a
// goroutine, so sharing one would be a data race on exactly what Rule 110
// forbids. netcheck.RunStep copies for this reason.
type stageDoneMsg struct {
	gen     int // must match Model.runGen; a superseded run's results are discarded
	stage   netcheck.StageID
	next    int // index into netcheck.Steps() of the stage still to run
	results netcheck.Results
}

// Model represents the network diagnostics view
type Model struct {
	config *config.Config
	width  int
	height int

	// Active tab (tabDiagnostics, tabPorts, tabInterfaces or tabForward)
	activeTab       int
	portsModel      *PortsModel
	interfacesModel *InterfacesModel
	forwardModel    *ForwardModel

	state ViewState

	// Form inputs
	targetInput    textinput.Model
	portInput      textinput.Model
	dnsServerInput textinput.Model
	focusedField   int

	// Running state
	runGen     int // incremented each run; results from a superseded run are dropped
	runStage   netcheck.StageID
	runStep    int
	totalSteps int

	// Results
	results     netcheck.Results
	verdict     netcheck.Verdict
	checksTable datatable.Model[netcheck.Check]
	filterBar   components.FilterBar

	// Details: one check explained
	detailsViewport viewport.Model
	selected        netcheck.Check

	// footer is the one line of transient state below the tab bar (Rule 128).
	footer components.FooterMessage

	// OriginView is where esc returns to from StateResults, when set. Empty
	// means netdiag was opened directly (the command line), and esc there
	// stays inside the view — resetting to the form, as it always has.
	OriginView command.ViewType
}

// New creates a new netdiag view
func New(cfg *config.Config) *Model {
	targetIn := textinput.New()
	theme.StyleTextInput(&targetIn)
	targetIn.Placeholder = "hostname or IP address"
	targetIn.CharLimit = 256
	targetIn.Focus()

	portIn := textinput.New()
	theme.StyleTextInput(&portIn)
	portIn.Placeholder = defaultPort
	portIn.CharLimit = 10

	dnsIn := textinput.New()
	theme.StyleTextInput(&dnsIn)
	// Empty means the system resolver, and that is the answer the user cares
	// about: it is the one their own traffic uses. The old default read the
	// first nameserver out of /etc/resolv.conf, which does not exist on Windows.
	dnsIn.Placeholder = "system resolver"
	dnsIn.CharLimit = 64

	return &Model{
		config:          cfg,
		state:           StateInput,
		activeTab:       tabDiagnostics,
		portsModel:      newPortsModel(time.Duration(cfg.Network.PortsRefreshInterval) * time.Second),
		interfacesModel: newInterfacesModel(),
		forwardModel:    newForwardModel(),
		targetInput:     targetIn,
		portInput:       portIn,
		dnsServerInput:  dnsIn,
		focusedField:    fieldTarget,
		filterBar:       components.NewFilterBarWithTokens([]components.FilterToken{{Label: problemsToken}}),
		checksTable: datatable.New(datatable.Config[netcheck.Check]{
			Columns: checkColumns(),
			// Pipeline order is content: resolve, reach, connect, TLS, HTTP is
			// the order the questions depend on one another. A table that
			// reorders itself destroys the one thing the layout says.
			SortColumn: -1,
		}),
	}
}

// NewWithTarget builds a view prefilled from an already-known target, for a
// producer elsewhere in the application (status's H, §3.66) rather than a
// user typing into the form. It stays a pure constructor — no tea.Cmd side
// effects — so the caller decides whether to also start the run, the same
// way uiviewer.NewWithSource hands back a model without loading anything.
func NewWithTarget(cfg *config.Config, t netcheck.Target) *Model {
	m := New(cfg)
	m.targetInput.SetValue(t.Host)
	if t.Port > 0 {
		m.portInput.SetValue(strconv.Itoa(t.Port))
	}
	m.dnsServerInput.SetValue(t.Resolver)
	return m
}

// buildTarget assembles what the form describes.
func (m *Model) buildTarget() (netcheck.Target, error) {
	host := strings.TrimSpace(m.targetInput.Value())
	if err := validateTarget(host); err != nil {
		return netcheck.Target{}, err
	}
	port := strings.TrimSpace(m.portInput.Value())
	if port == "" {
		port = defaultPort
	}
	if err := validatePort(port); err != nil {
		return netcheck.Target{}, err
	}
	n, _ := strconv.Atoi(port) // validatePort has already accepted it
	return netcheck.Target{
		Host:     host,
		Port:     n,
		Resolver: strings.TrimSpace(m.dnsServerInput.Value()),
	}, nil
}

// visibleChecks applies the filter bar to the results.
//
// The view filters and calls SetItems rather than leaning on the table's own
// search, for the reason security and status do: this decides which rows exist
// at all, where a FilterBar query narrows a list that is already settled.
func (m *Model) visibleChecks() []netcheck.Check {
	all := m.results.All()
	query := strings.ToLower(m.filterBar.SearchQuery())
	onlyProblems := m.filterBar.IsTokenActive(problemsToken)

	out := make([]netcheck.Check, 0, len(all))
	for _, c := range all {
		if onlyProblems && (c.Verdict == netcheck.OK || c.Verdict == netcheck.NotApplicable) {
			continue
		}
		if query != "" && !matchesQuery(c, query) {
			continue
		}
		out = append(out, c)
	}
	return out
}

func matchesQuery(c netcheck.Check, query string) bool {
	return strings.Contains(strings.ToLower(c.Title), query) ||
		strings.Contains(strings.ToLower(c.Summary), query)
}

// checkSettings is what the config says the pipeline should wait for and send.
//
// Read on every run rather than captured at construction: the configuration
// view rebuilds this model on save, but a run already in flight holds its own
// copy through the message chain, and taking the values here keeps the two from
// disagreeing halfway down the pipeline.
//
// netcheck.Settings.normalize fills in anything non-positive, so a hand-edited
// zero becomes the default rather than a dial with no deadline.
func (m *Model) checkSettings() netcheck.Settings {
	return netcheck.Settings{
		CheckTimeout:     time.Duration(m.config.Network.CheckTimeout) * time.Second,
		PingCount:        m.config.Network.PingCount,
		ExpiryWarnWindow: time.Duration(m.config.Network.CertExpiryWarnDays) * 24 * time.Hour,
	}
}

package netdiag

import (
	"log"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/forward"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init implements tea.Model
func (m *Model) Init() tea.Cmd {
	return tea.Batch(
		textinput.Blink,
		m.portsModel.initPorts(),
		m.interfacesModel.initInterfaces(),
		// The forwards live on the router, which broadcasts when they change.
		// A view built after the last change was not there for it, so it asks
		// once on the way in — the role sendJobsTo plays for the job registry.
		forward.Refresh,
	)
}

// Running reports whether a diagnostic is walking its stages now, which is what
// the router asks before it would rebuild the view: dropping it mid-run would
// discard the run without a word.
func (m *Model) Running() bool { return m.state == StateRunning }

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	case tabForward:
		return m.forwardModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// FilterBarVisible implements app.FilterBarView.
func (m *Model) FilterBarVisible() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.table.FilterBar().IsVisible()
	case tabForward:
		return m.forwardModel.table.FilterBar().IsVisible()
	}
	return m.activeTab == tabDiagnostics && m.filterBar.IsVisible()
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		return m, nil

	// The router's animation frame: the blink phase of the Ports dot and of the
	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// four: the timer fires wherever the user has since navigated.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	return m, nil
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	m.results = msg.results
	m.rebuildChecksTable()

	steps := netcheck.Steps()
	if msg.next >= len(steps) {
		m.state = StateResults
		m.verdict = netcheck.Summarize(m.results.All())
		log.Printf("INFO [netdiag] run finished: verdict=%s over %d checks",
			m.verdict, len(m.results.All()))
		return m, nil
	}

	m.runStep = msg.next
	m.runStage = steps[msg.next]

	tg, err := m.buildTarget()
	if err != nil {
		// The form has not changed since the run started, so this cannot
		// normally fail. Reporting it beats continuing with a target nobody
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

// handlePaste gives pasted text to the field that has the keyboard on the tab on
// screen. It never reaches the key handlers, so no action fires (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabPorts:
		m.portsModel, cmd = m.portsModel.update(msg)
	case tabInterfaces:
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
	case tabForward:
		m.forwardModel, cmd = m.forwardModel.update(msg)
	default:
		switch {
		case m.filterBar.InEditMode():
			m.filterBar, cmd = m.filterBar.Update(msg)
			m.rebuildChecksTable()
		case m.state == StateInput:
			return m.updateActiveInput(msg)
		}
	}
	return m, cmd
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the three tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	}
	return m, nil
}

// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")
}

func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "down":
		m.moveFocus(1)
		return m, nil
	case "up":
		m.moveFocus(-1)
		return m, nil
	case "enter":
		// enter runs from anywhere in the form: with three fields and one
		// button there is nothing else it could mean, and making the user walk
		// to the button first is a step that buys nothing.
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

func (m *Model) handleKeyResults(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openDetails()
	case "esc":
		// No origin view means netdiag was opened directly (the command
		// line), so esc stays inside it and resets to the form, as it
		// always has. An origin means it was opened prefilled from
		// elsewhere (status's H, §3.66), and esc returns there instead.
		if m.OriginView == "" {
			return m.resetToForm()
		}
		origin := m.OriginView
		return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
	case "ctrl+r":
		return m.StartRun()
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "p":
		m.filterBar.SetTokenActive(problemsToken, !m.filterBar.IsTokenActive(problemsToken))
		m.rebuildChecksTable()
		return m, nil
	case keymap.New:
		// Always resets to the form, regardless of OriginView — the one way
		// to run a wholly new diagnostic without first leaving to wherever
		// this run was opened from. Found missing the day §3.66 shipped H:
		// esc alone left no way back to the form once an origin was set, and
		// re-entering netdiag through the command line landed on the same
		// frozen results with the same problem, since the cached view (and
		// its OriginView) is reused rather than rebuilt.
		return m.resetToForm()
	}
	return m, m.checksTable.Update(msg)
}

func (m *Model) handleKeyDetails(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.state = StateResults
		return m, nil
	case "up":
		m.detailsViewport.ScrollUp(1)
	case "down":
		m.detailsViewport.ScrollDown(1)
	case "pgup":
		m.detailsViewport.HalfPageUp()
	case "pgdown":
		m.detailsViewport.HalfPageDown()
	case "home":
		m.detailsViewport.GotoTop()
	case "end":
		m.detailsViewport.GotoBottom()
	}
	return m, nil
}

func (m *Model) openDetails() (*Model, tea.Cmd) {
	c, ok := m.checksTable.Selected()
	if !ok {
		return m, nil
	}
	m.selected = c
	m.state = StateDetails
	m.resizeDetailsViewport()
	m.detailsViewport.SetContent(m.renderDetailsContent(m.detailsViewport.Width()))
	m.detailsViewport.GotoTop()
	return m, nil
}

func (m *Model) resetToForm() (*Model, tea.Cmd) {
	m.state = StateInput
	m.focusedField = fieldTarget
	m.targetInput.Focus()
	m.results = netcheck.Results{}
	m.verdict = netcheck.Unknown
	m.filterBar.ClearSearch()
	m.filterBar.SetTokenActive(problemsToken, false)
	m.rebuildChecksTable()
	// Starting over severs the tie to wherever this run was opened from: the
	// next run is not "the monitor status sent here" anymore, so esc on its
	// results should not try to leave for a view this new target has nothing
	// to do with.
	m.OriginView = ""
	return m, nil
}

package netdiag

import (
	"context"
	"net/netip"
	"time"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// reasonPathUnsupported is shown when the platform cannot trace a path. The
	// header greys enter out and the handler refuses with the same text.
	reasonPathUnsupported = "The path trace is not supported on this platform"

	// defaultPathResolveTimeout bounds the name resolution of a target.
	defaultPathResolveTimeout = 5 * time.Second

	// pathInputCharLimit holds a 253-character host name, a colon and a port.
	pathInputCharLimit = 262
)

// pathState is where the Path tab is in its life cycle.
type pathState int

const (
	// pathEditing: the target field has the keyboard.
	pathEditing pathState = iota
	// pathRunning: a trace is in flight; the field is blurred.
	pathRunning
	// pathDone: a trace ended (or was canceled); the hops stay on screen.
	pathDone
)

// PathModel is the Path tab: a target field above a table of hops that fills
// in while the trace runs.
type PathModel struct {
	width int

	engine         pathEngine
	resolveTimeout time.Duration

	input textinput.Model
	table datatable.Model[nettrace.Hop]

	state  pathState
	target pathTarget
	addr   netip.Addr
	// hops is what the engine reported so far; the table shows
	// visiblePathHops(hops). At done it is replaced by Result.Hops.
	hops   []nettrace.Hop
	result *nettrace.Result
	// errText is the persistent footer error of a run that never traced. It is
	// cleared by a change of the field or by the next launch, not by a timer.
	errText string

	// gen identifies the run whose messages are accepted; cancel and msgs
	// belong to that run.
	gen    int
	cancel context.CancelFunc
	msgs   <-chan tea.Msg

	footer components.FooterMessage
}

func newPathModel(e pathEngine) *PathModel {
	in := textinput.New()
	theme.StyleTextInput(&in)
	in.Placeholder = "hostname or IPv4 address[:port]"
	in.CharLimit = pathInputCharLimit
	in.Focus()

	return &PathModel{
		engine:         e,
		resolveTimeout: defaultPathResolveTimeout,
		input:          in,
		table: datatable.New(datatable.Config[nettrace.Hop]{
			Columns:    pathColumns(),
			SortColumn: -1, // the path order is the content
		}),
	}
}

// InEditMode reports whether the target field has the keyboard.
func (pm *PathModel) InEditMode() bool { return pm.state == pathEditing }

func (pm *PathModel) running() bool { return pm.state == pathRunning }

func (pm *PathModel) resize(width, height int) {
	pm.width = width
	pm.input.SetWidth(max(width-ansi.StringWidth(pathBarLabel)-4, 10))
	pm.table.Resize(width, max(height, 3))
}

// launchable is the one answer to "can a trace start here", read by the header
// and by the handler (Rule 130).
func (pm *PathModel) launchable() shortcut.Availability {
	if pm.engine.supported() != nil {
		return shortcut.Unavailable(reasonPathUnsupported)
	}
	return shortcut.Availability{}
}

func (pm *PathModel) update(msg tea.Msg) (*PathModel, tea.Cmd) {
	switch msg := msg.(type) {
	case pathResolvedMsg:
		return pm.handleResolved(msg)
	case pathHopMsg:
		return pm.handleHop(msg)
	case pathDoneMsg:
		return pm.handleDone(msg)
	case tea.KeyPressMsg:
		return pm.handleKey(msg)
	case tea.PasteMsg:
		return pm.handlePaste(msg)
	}
	pm.footer.Handle(msg)
	return pm, nil
}

func (pm *PathModel) handleResolved(msg pathResolvedMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.addr = msg.addr
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleHop(msg pathHopMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.hops = append(pm.hops, msg.hop)
	pm.table.SetItems(visiblePathHops(pm.hops))
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleDone(msg pathDoneMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.releaseRun()
	if msg.err != nil {
		pm.hops = nil
		pm.table.SetItems(nil)
		pm.errText = pathErrorLabel(pm.target.Host, msg.err)
		pm.state = pathEditing
		return pm, pm.input.Focus()
	}
	res := msg.result
	pm.result = &res
	pm.hops = res.Hops
	pm.table.SetItems(visiblePathHops(res.Hops))
	pm.state = pathDone
	return pm, nil
}

// releaseRun cancels the run's context (releasing it) and forgets its channel.
func (pm *PathModel) releaseRun() {
	if pm.cancel != nil {
		pm.cancel()
		pm.cancel = nil
	}
	pm.msgs = nil
}

func isPathNavKey(key string) bool {
	switch key {
	case "up", "down", "pgup", "pgdown", "home", "end":
		return true
	}
	return false
}

func (pm *PathModel) handleKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	key := msg.String()
	if isPathNavKey(key) {
		return pm, pm.table.Update(msg)
	}
	switch pm.state {
	case pathEditing:
		return pm.handleEditKey(msg)
	case pathRunning:
		if key == "esc" {
			return pm.cancelRun()
		}
	case pathDone:
		switch key {
		case "enter":
			return pm.launch(pm.target)
		case "esc":
			pm.state = pathEditing
			return pm, pm.input.Focus()
		}
	}
	return pm, nil
}

func (pm *PathModel) handleEditKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return pm.launchFromInput()
	case "esc", "tab", "shift+tab":
		return pm, nil
	}
	return pm.updateInput(msg)
}

func (pm *PathModel) handlePaste(msg tea.PasteMsg) (*PathModel, tea.Cmd) {
	if pm.state != pathEditing {
		return pm, nil // a paste reaches the focused field only (Rule 111)
	}
	return pm.updateInput(msg)
}

// updateInput hands msg to the field; a changed value drops the stale error.
func (pm *PathModel) updateInput(msg tea.Msg) (*PathModel, tea.Cmd) {
	before := pm.input.Value()
	var cmd tea.Cmd
	pm.input, cmd = pm.input.Update(msg)
	if pm.input.Value() != before {
		pm.errText = ""
	}
	return pm, cmd
}

func (pm *PathModel) launchFromInput() (*PathModel, tea.Cmd) {
	tg, err := parsePathTarget(pm.input.Value())
	if err != nil {
		return pm, pm.footer.Error(capitalize(err.Error()))
	}
	return pm.launch(tg)
}

// launch starts a run: the model changes here, in Update; the Cmd only does I/O.
func (pm *PathModel) launch(tg pathTarget) (*PathModel, tea.Cmd) {
	if a := pm.launchable(); !a.Enabled() {
		return pm, pm.footer.Warn(a.Reason)
	}
	pm.releaseRun()
	pm.gen++
	pm.target = tg
	pm.addr = netip.Addr{}
	pm.hops = nil
	pm.result = nil
	pm.errText = ""
	pm.footer.Clear()
	pm.table.SetItems(nil)

	ctx, cancel := context.WithCancel(context.Background())
	ch := make(chan tea.Msg, pathChanCap)
	pm.cancel, pm.msgs = cancel, ch
	pm.input.Blur()
	pm.state = pathRunning
	return pm, startPathRun(ctx, pm.gen, tg, pm.resolveTimeout, pm.engine, ch)
}

// cancelRun answers esc at once: the run's late messages are dropped by the
// generation bump, the hops already seen stay on screen.
func (pm *PathModel) cancelRun() (*PathModel, tea.Cmd) {
	pm.releaseRun()
	pm.gen++
	pm.result = &nettrace.Result{Outcome: nettrace.OutcomeCancelled}
	pm.state = pathDone
	return pm, nil
}

// startPathRun builds the launch Cmd from values only, so that no closure
// reads the model (Rule 110).
func startPathRun(ctx context.Context, gen int, tg pathTarget, timeout time.Duration, e pathEngine, ch chan tea.Msg) tea.Cmd {
	return tea.Batch(
		func() tea.Msg {
			producePath(ctx, gen, tg, timeout, e, ch)
			return nil
		},
		waitForPathMsg(ch),
	)
}

