package netdiag

import (
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// GetTitle implements HeaderView
func (m *Model) GetTitle() string {
	base := theme.IconNetwork + " Network"
	if m.state == StateDetails {
		if label := m.selected.Title; label != "" {
			detailStyle := lipgloss.NewStyle().Foreground(theme.ColorPrimary).Background(theme.ColorBackground)
			return base + detailStyle.Render(" "+theme.IconChevronRight+" "+label)
		}
	}
	return base
}

// GetIcon implements HeaderView
func (m *Model) GetIcon() string {
	return theme.IconNetwork
}

// GetShortcuts implements HeaderView
func (m *Model) GetShortcuts() shortcut.Shortcuts {
	tabShortcuts := shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
	}

	if m.activeTab == tabInterfaces {
		// A read in flight greys the table's keys rather than removing them:
		// the tab is the same screen either side of a refresh, and a column
		// that empties and refills on every ctrl+r is the flicker Rule 130 is
		// about. ctrl+r stays lit — asking again is exactly what still applies.
		loading := m.interfacesModel.loading
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: "ctrl+r", Description: "Refresh"},
			{Key: "/", Description: "Filter", Disabled: loading},
			{Key: ".", Description: "Sort", Disabled: loading},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabForward {
		if m.forwardModel.form != nil {
			// A form is a mode, so the whole list is replaced rather than
			// greyed (Rule 130): greying N and K here would show the union of
			// two vocabularies.
			return shortcut.Shortcuts{
				// ←→ only cycles the type, so it greys elsewhere (Rule 130).
				{Key: "←→", Description: "Change type", Disabled: !m.forwardModel.form.TypeFocused()},
				{Key: "enter", Description: "Open the forward"},
				{Key: "esc", Description: "Cancel"},
			}
		}
		if m.forwardModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: keymap.New, Description: "New forward"},
			// Nothing to pause, resume or delete on an empty table (Rule 130).
			{Key: "space", Description: m.forwardModel.toggleLabel(), Disabled: !m.forwardModel.switchable().Enabled()},
			{Key: keymap.Kill, Description: "Delete forward", Disabled: !m.forwardModel.closable().Enabled()},
			{Key: "/", Description: "Search"},
			{Key: ".", Description: "Sort"},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabPorts {
		if m.portsModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "t", Description: "Toggle TCP"},
			{Key: "u", Description: "Toggle UDP"},
			{Key: "l", Description: "Toggle LISTEN"},
			{Key: "e", Description: "Toggle ESTAB"},
			{Key: "n", Description: "Toggle numeric"},
			{Key: "z", Description: "Reset filters"},
			{Key: "/", Description: "Search"},
			{Key: "space", Description: "Pause/Resume"},
			// A socket the system declines to attribute carries no PID, so
			// there is nothing to signal (Rule 130).
			{Key: keymap.Kill, Description: "Kill process", Disabled: !m.portsModel.killable().Enabled()},
			{Key: "?", Description: "Help"},
		}
		return append(tabShortcuts, sc...)
	}

	switch m.state {
	case StateInput:
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: "enter", Description: "Run the checks"},
			{Key: "?", Description: "Help"},
		}...)
	case StateRunning:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Cancel and keep what completed"},
		}
	case StateResults:
		if m.filterBar.InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "enter", Description: "Explain the check"},
		}
		label := "Show problems only"
		if m.filterBar.IsTokenActive(problemsToken) {
			label = "Show every check"
		}
		escLabel := "New diagnostic"
		if m.OriginView != "" {
			escLabel = "Go back"
		}
		sc = append(sc,
			shortcut.Shortcut{Key: "p", Description: label},
			shortcut.Shortcut{Key: "/", Description: "Search"},
			shortcut.Shortcut{Key: "ctrl+r", Description: "Run again"},
			shortcut.Shortcut{Key: "esc", Description: escLabel},
		)
		if m.OriginView != "" {
			// Otherwise esc already reads "New diagnostic" and does exactly
			// this — advertising both here would just say the same thing
			// twice (Rule 138). With an origin, esc means "go back" instead,
			// so this is the only key left that starts a fresh target.
			sc = append(sc, shortcut.Shortcut{Key: keymap.New, Description: "New diagnostic"})
		}
		sc = append(sc, shortcut.Shortcut{Key: "?", Description: "Help"})
		return append(tabShortcuts, sc...)
	case StateDetails:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Go back to the checks"},
		}
	}
	return tabShortcuts
}

// GetHeaderInfo implements HeaderView.
//
// The verdict is the one line worth spending: it is the answer to the question
// the view exists for, and reading it off ten rows is what the header is
// supposed to save. It appears only once there is a run to summarise.
func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
	if m.activeTab == tabInterfaces {
		return append(info, shortcut.HeaderInfo{
			Key:   "Interfaces",
			Value: m.interfacesModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabPorts {
		return append(info, shortcut.HeaderInfo{
			Key:   "Ports",
			Value: m.portsModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabForward {
		return append(info, shortcut.HeaderInfo{
			Key:   "Forwards",
			Value: m.forwardModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab != tabDiagnostics || m.state == StateInput {
		return info
	}
	if len(m.results.All()) == 0 {
		return info
	}
	return append(info, shortcut.HeaderInfo{
		Key:   "Verdict",
		Value: m.verdict.String(),
		Style: verdictHeaderStyle(m.verdict),
	})
}

// verdictHeaderStyle colours the headline the way the table colours a cell.
func verdictHeaderStyle(v netcheck.Verdict) lipgloss.Style {
	switch v {
	case netcheck.Fail:
		return theme.SeverityTextStyle("CRITICAL")
	case netcheck.Warn:
		return theme.SeverityTextStyle("MEDIUM")
	case netcheck.OK:
		return theme.StatusOKStyle
	default:
		return theme.DimStyle
	}
}

// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
func (m *Model) GetFooterHeight() int {
	if m.activeTab == tabPorts {
		return 3 + m.portsModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabDiagnostics {
		return 3 + m.filterBar.ExtraHeight()
	}
	if m.activeTab == tabInterfaces {
		return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabForward {
		return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
	}
	return 3
}

// RenderFooter implements FooterView
func (m *Model) RenderFooter(width int) string {
	var parts []string

	// The active tab's filter bar renders above the tab bar when visible.
	switch {
	case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
		parts = append(parts, m.portsModel.table.FilterBar().View())
	case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
		parts = append(parts, m.filterBar.View())
	case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
		parts = append(parts, m.interfacesModel.table.FilterBar().View())
	case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
		parts = append(parts, m.forwardModel.table.FilterBar().View())
	}

	tabs := theme.RenderTabs([]theme.TabItem{
		{Label: "Diagnostics"},
		{Label: "Ports"},
		{Label: "Interfaces"},
		{Label: "Forward"},
	}, m.activeTab)
	tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)

	// The message belongs to the tab that raised it: each sub-model keeps its
	// own, so switching away does not carry one tab's notice onto another.
	footer, status := m.activeFooter()
	parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
	return strings.Join(parts, "\n")
}

// activeFooter resolves the message line of whichever tab is on screen, and the
// status that tab derives on every frame.
func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
	switch m.activeTab {
	case tabPorts:
		return &m.portsModel.footer, m.portsModel.statusLine()
	case tabInterfaces:
		return &m.interfacesModel.footer, m.interfacesModel.statusLine()
	case tabForward:
		return &m.forwardModel.footer, m.forwardModel.status()
	}
	return &m.footer, m.statusLine()
}

// statusLine is what the diagnostics tab derives on every frame: a progress
// label while the pipeline walks, and nothing once it has an answer. It is a
// status rather than a footer message because it is a state, not an event —
// a message expires after three seconds and a run outlives that (Rule 128).
func (m *Model) statusLine() components.Status {
	if m.state == StateRunning {
		return components.Status{Text: m.progressLabel(), Activity: true}
	}
	return components.Status{}
}

// GetHelpContent implements help.Provider
func (m *Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "Network",
		Description: "Four-tab view: check whether a host is reachable and its certificate chain sound (Diagnostics), monitor live ports (Ports), inspect this machine's network interfaces (Interfaces), or redirect a local port to a host:port, or give a service a name (Forward).",
		KeyBindings: []help.KeyBinding{
			// Tab navigation
			{Key: "tab / shift+tab", Description: "Cycle between the Diagnostics, Ports, Interfaces and Forward tabs"},
			// Diagnostics
			{Key: "↑ / ↓", Description: "Navigate between fields (Diagnostics tab)"},
			{Key: "enter (form)", Description: "Run the checks against the target"},
			{Key: "esc (running)", Description: "Cancel the run and keep what completed"},
			{Key: "enter (results)", Description: "Explain the selected check"},
			{Key: "p", Description: "Show problems only / show every check (Diagnostics tab)"},
			{Key: "/", Description: "Search checks by name or observation (Diagnostics tab)"},
			{Key: "ctrl+r", Description: "Run the checks again"},
			{Key: "esc (results)", Description: "Back to the target form, or back to wherever this run was opened from (e.g. status's H) when it was opened prefilled"},
			{Key: keymap.New + " (results)", Description: "Start a new diagnostic — always resets to the form, even when esc there means \"go back\""},
			{Key: "esc (details)", Description: "Back to the checks"},
			{Key: "pgup / pgdown", Description: "Scroll half page up / down"},
			// Ports tab
			{Key: "t", Description: "Toggle TCP filter — cumulative with u (Ports tab)"},
			{Key: "u", Description: "Toggle UDP filter — cumulative with t (Ports tab)"},
			{Key: "l", Description: "Toggle LISTEN state filter — cumulative with e (Ports tab)"},
			{Key: "e", Description: "Toggle ESTAB state filter — cumulative with l (Ports tab)"},
			{Key: "n", Description: "Toggle numeric addresses / reverse-DNS host names (Ports tab)"},
			{Key: "z", Description: "Reset all active filters (Ports tab)"},
			{Key: "/", Description: "Search ports by address, process or PID (Ports tab)"},
			{Key: "space (Ports)", Description: "Pause / resume auto-refresh (Ports tab)"},
			{Key: keymap.Kill, Description: "Send SIGKILL to the selected process, after confirmation (Ports tab)"},
			// Interfaces tab
			{Key: "/", Description: "Search interfaces by name, MAC or address (Interfaces tab)"},
			{Key: ".", Description: "Cycle the sort column (Interfaces tab)"},
			{Key: "ctrl+r", Description: "Re-read the interfaces (Interfaces tab)"},
			// Forward tab
			{Key: keymap.New, Description: "Open a new forward — TCP, or a named HTTP route (Forward tab)"},
			{Key: "space", Description: "Pause the selected forward, or resume a paused or unbound one (Forward tab)"},
			{Key: keymap.Kill, Description: "Delete the selected forward, after confirmation (Forward tab)"},
			{Key: "/", Description: "Search forwards by port or target (Forward tab)"},
			{Key: ".", Description: "Cycle the sort column (Forward tab)"},
		},
		Sections: []help.Section{
			{
				Title: "Diagnostics Tab — What it asks",
				Body: "One target, one run. The checks follow from the target and from what has " +
					"already failed, so there is nothing to select.\n\n" +
					"DNS resolution     - the name, against the resolver your own traffic uses\n" +
					"Reverse DNS        - the name an address publishes (literal targets only)\n" +
					"Local route        - which interface carries this target, and from which address\n" +
					"ICMP echo          - reachability; a filtered echo is a warning, never a failure\n" +
					"TCP connect        - the port you named, and the answer that decides reachability\n" +
					"TLS handshake      - whether the port speaks TLS at all\n" +
					"Certificate chain  - verified against this machine's store, intermediates included\n" +
					"Hostname match     - whether the certificate names the host you dialled\n" +
					"Certificate expiry - the validity window, in days\n" +
					"TLS version        - the negotiated protocol version\n" +
					"HTTP response      - whether the service answers, over the scheme actually spoken",
			},
			{
				Title: "Diagnostics Tab — Reading the verdicts",
				Body: "OK      - the objective is met\n" +
					"WARN    - met, but something is off: a certificate near expiry, a deprecated\n" +
					"          version, a chain that verifies here and will not elsewhere\n" +
					"FAIL    - the objective is not met\n" +
					"N/A     - no meaning for this target, or blocked by a check above it\n" +
					"UNKNOWN - the check could not look, which is not the same as a pass\n\n" +
					"A stage whose dependency failed does not run: its checks come back N/A naming " +
					"what blocked them, so a broken run reads as one failure and a named point of " +
					"rupture rather than as ten red rows.\n\n" +
					"Press enter on any row for what it means and what to do about it.",
			},
			indicator.Legend(),
			{
				Title: "Ports Tab — How it works",
				Body: "Reads this machine's TCP and UDP sockets every 2 seconds, in this process — no " +
					"container, no Docker. Shows the owning process name and PID where the system will " +
					"name one. K terminates that process, after a confirmation, with the rights DevDesk " +
					"itself has: another user's process or a service comes back refused rather than " +
					"silently killed elsewhere.\n\n" +
					"n toggles reverse DNS on the addresses. Host names only — port numbers stay " +
					"numeric, because a service name would be DevDesk's guess and not the system's.\n\n" +
					"While K is killing a process, the dot on its sockets (" + indicator.Glyph(indicator.Running, true) +
					") is lit and the footer names the kill.",
			},
			{
				Title: "Forward Tab — How it works",
				Body: "Redirects traffic to a host:port, inside this process — no privilege, " +
					"no container, nothing written to a system file. Use it to reach a port nothing " +
					"published: a container's EXPOSEd port, or a service on another machine.\n\n" +
					"N opens a form with a Type field, changed with ← →. TCP redirects a local port " +
					"to a host:port. HTTP gives the target a name instead of a port: fill in Name " +
					"and Target, and http://<name>:<proxy port> reaches it.\n\n" +
					"A name must end in .localhost, such as api.localhost — nothing else is " +
					"accepted. That suffix is reserved for this machine, so it needs no DNS entry and " +
					"no privilege; any other name would not resolve. Every named route is served on " +
					"the same port, network.proxy_port (8080 by default, in the network tab of the " +
					"configuration), and the request's Host header picks the target — so " +
					"http://api.localhost:8080 and http://app.localhost:8080 are two services on one " +
					"port. The port stays in the URL because 80 is privileged. It is HTTP only: " +
					"https would need a certificate your browser trusts. A name that is not known " +
					"gets a page listing the ones that are.\n\n" +
					"Everything listens on 127.0.0.1 only, so it is available to this machine and " +
					"not to the network — a service kept off the LAN stays off it. A TCP forward's " +
					"local port has to be 1024 or above, and cannot be the proxy's: anything below " +
					"needs privileges DevDesk does not ask for, and there is no unprivileged way " +
					"around that on Linux or macOS.\n\n" +
					"The target is dialled once before the port is bound, so an address that answers " +
					"nothing is refused immediately instead of failing later at the first client. A " +
					"container's own address is reachable from the host on native Linux; under " +
					"Docker Desktop it lives in the virtual machine and does not route out of it.\n\n" +
					"Forwards are saved in ~/.devdesk/forwards.yaml and reopened when DevDesk " +
					"starts. They survive a context switch — a local port pointed at a host:port " +
					"belongs to no context — but the listener itself cannot outlive the process, so " +
					"what comes back is the list, bound again.\n\n" +
					"A forward that cannot be bound at launch — its port is taken, or its target is " +
					"not up yet — is not deleted. Its row reads unbound, the last error says why, and " +
					"space tries again. Space also pauses a live forward: the port is released and the " +
					"row stays, paused, until you resume it. K deletes a forward for good, and asks " +
					"first.",
			},
			{
				Title: "Interfaces Tab — How it works",
				Body: "Lists this machine's network interfaces, read in this process — no container, " +
					"no Docker. Name, state, MTU, hardware address, error counters and every address " +
					"the interface carries. ctrl+r re-reads them.\n\n" +
					"A dash is not a zero. RX err and TX err show a dash when the counters could not " +
					"be read at all, which is a different thing from an interface that has dropped " +
					"nothing; MTU shows one where the platform reports no figure, as Windows does " +
					"for its loopback.\n\n" +
					"This was the Topology tab. Its routing table, ARP cache and firewall summary " +
					"were read by running ip and iptables in a container on the Docker Desktop VM, " +
					"so they described the VM and not this machine. Nothing portable produces them, " +
					"so they were removed rather than translated — and the route question moved to " +
					"the Diagnostics tab, where it is asked about a target: the Local route check " +
					"names the interface your traffic to that host actually leaves by.",
			},
			{
				Title: "Where the checks run",
				Body: "Everything here runs in this process, on this machine's network stack: the " +
					"diagnostic checks, the socket table and the interfaces alike. They answer for " +
					"the resolver, the routing table, the sockets and the VPN you are actually on, " +
					"and nothing needs Docker.\n\n" +
					"The route trace used to be the exception. It ran traceroute in a container " +
					"started with --network host, which on Docker Desktop is the Linux VM's " +
					"namespace — so it traced the path from the VM and not from here, and the two " +
					"are not the same network. It was removed rather than kept with a caveat.\n\n" +
					"What replaced it, for the question people actually asked: the Local route " +
					"check names the interface and source address your traffic to this target " +
					"leaves by. That is the split-tunnel answer, read from this machine.",
			},
		},
	}
}

package netdiag

import (
	"fmt"
	"strings"
	"time"

	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View is the Bubble Tea v2 face of Render: the content only. The terminal
// state (alternate screen, colours) belongs to whoever owns the program.
func (m *Model) View() tea.View { return tea.NewView(m.Render()) }

// Render implements tea.Model
func (m *Model) Render() string {
	switch m.activeTab {
	case tabPorts:
		// The kill confirmation is centred over the tab, like every other
		// modal (Rule 112).
		if modal := m.portsModel.confirmModal; modal != nil {
			return lipgloss.Place(
				m.width, m.height,
				lipgloss.Center, lipgloss.Center,
				modal.View(),
				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)),
			)
		}
		return m.portsModel.view()
	case tabInterfaces:
		return m.interfacesModel.view()
	case tabForward:
		// The stop confirmation is centred over the tab, like every other
		// modal (Rule 112).
		if modal := m.forwardModel.confirmModal; modal != nil {
			return lipgloss.Place(
				m.width, m.height,
				lipgloss.Center, lipgloss.Center,
				modal.View(),
				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)),
			)
		}
		return m.forwardModel.view()
	}
	switch m.state {
	case StateInput:
		return m.renderInputForm()
	case StateRunning, StateResults:
		// The table stays on screen while the pipeline runs, filling in as each
		// stage lands. A body that swaps itself for a spinner loses its header
		// and its columns (Rule 139), and here it would also throw away the
		// rows already answered.
		return m.renderChecks()
	case StateDetails:
		return m.detailsViewport.View()
	}
	return ""
}

func (m *Model) renderInputForm() string {
	var b strings.Builder

	b.WriteString(m.renderTextInputField("Target", m.targetInput, fieldTarget))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("Port", m.portInput, fieldPort))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("DNS Server", m.dnsServerInput, fieldDNSServer))
	b.WriteString("\n\n")
	b.WriteString("  " + theme.RenderButton("Run Diagnostics", m.focusedField == fieldButton, "primary"))

	return lipgloss.NewStyle().
		Padding(1).
		Background(theme.ColorBackground).
		Render(b.String())
}

func (m *Model) renderTextInputField(label string, input textinput.Model, fieldIdx int) string {
	prefix := "  "
	if m.focusedField == fieldIdx {
		prefix = theme.IconCircleSmall + " "
	}
	return theme.KeyStyle.Render(prefix+label+" "+theme.IconChevronRight+" ") + input.View()
}

// renderChecks draws the results table. An empty table — the run produced
// none, or the "problems" filter hid every one because they all passed —
// stays a table (Rule 139): its header and no rows. The Verdict header field
// already answers "did everything pass?" once there is a run to summarise.
func (m *Model) renderChecks() string {
	return m.checksTable.View()
}

// checkColumns describes the results table.
//
// A row is a question that got an answer, so the columns are the question, the
// answer, and what was observed — never the name of a tool.
func checkColumns() []datatable.Column[netcheck.Check] {
	return []datatable.Column[netcheck.Check]{
		{
			Title: "Check", Sizing: datatable.SizingContent, MinWidth: 20,
			Cell: func(c netcheck.Check) string { return c.Title },
		},
		{
			Title: "Verdict", Sizing: datatable.SizingFixed, MinWidth: 9,
			Cell:  verdictCell,
			Style: verdictStyle,
		},
		{
			Title: "Observed", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1,
			Cell: func(c netcheck.Check) string { return c.Summary },
		},
	}
}

// verdictCell is plain text: the colour is decided by Style (Rule 122).
func verdictCell(c netcheck.Check) string {
	switch c.Verdict {
	case netcheck.OK:
		return theme.IconOK + " OK"
	case netcheck.Warn:
		return theme.IconWarning + " WARN"
	case netcheck.Fail:
		return theme.IconError + " FAIL"
	case netcheck.NotApplicable:
		return theme.IconCanceled + " N/A"
	default:
		return theme.IconCanceled + " ?"
	}
}

// verdictStyle gives each verdict its own colour.
//
// Rule 122 reserves colour for what is worth spotting without reading, and its
// worked example — a container list where nearly every row is `running` —
// argues against colouring the nominal state. This column is the other case,
// and the difference is what the reader is doing: a diagnostic is read once,
// end to end, to find where it broke. Every row is a distinct question, there
// is no majority state to drown in, and the column *is* the answer. So the four
// outcomes are told apart at a glance, as Rule 121 has status indicators do.
//
// The one that is not a colour choice is UNKNOWN. It must not share N/A's dim:
// "no meaning here" and "we could not look" are the distinction the whole
// package is built on — the reason Verdict's zero value is Unknown and the
// reason SecretVerdict returns a *bool. Rendering them alike on screen would
// give back exactly what the types take care to keep apart.
func verdictStyle(c netcheck.Check) lipgloss.Style {
	switch c.Verdict {
	case netcheck.Fail:
		return theme.SeverityTextStyle("CRITICAL")
	case netcheck.Warn:
		return theme.SeverityTextStyle("MEDIUM")
	case netcheck.OK:
		return theme.StatusOKStyle
	case netcheck.Unknown:
		return theme.SeverityTextStyle("HIGH")
	default: // NotApplicable — nothing was asked, so nothing is worth spotting
		return theme.DimStyle
	}
}

// renderDetailsContent draws one check: what was observed, what it means, what
// to do, and the facts behind it.
func (m *Model) renderDetailsContent(width int) string {
	c := m.selected
	e := netcheck.Explain(c)

	var lines []string
	lines = append(lines, theme.EmptyLineBg(width))
	lines = append(lines, section(width, "Observed", e.Observed)...)
	lines = append(lines, section(width, "What it means", e.Means)...)
	if e.Do != "" {
		lines = append(lines, section(width, "What to do", e.Do)...)
	}

	if len(c.Facts) > 0 {
		lines = append(lines, theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" Details"), width))
		lines = append(lines, theme.EmptyLineBg(width))
		for _, f := range c.Facts {
			line := theme.KeyStyle.Render("  "+f.Key+" "+theme.IconChevronRight+" ") + theme.Bg(f.Value)
			lines = append(lines, theme.PadWithBg(line, width))
		}
		lines = append(lines, theme.EmptyLineBg(width))
	}

	if len(c.Phases) > 0 {
		lines = append(lines, theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" Timing"), width))
		lines = append(lines, theme.EmptyLineBg(width))
		lines = append(lines, phaseLines(c.Phases, c.Duration, width)...)
		lines = append(lines, theme.EmptyLineBg(width))
	}

	return strings.Join(lines, "\n")
}

// phaseLabelWidth fits the longest phase name ("Connect"/"Content", 7
// characters) plus one cell of breathing room before the bar starts.
const phaseLabelWidth = 8

// phaseLines renders one waterfall row per phase: a label, a bar proportional
// to the phase's share of total, and that share as a percentage. total is
// the check's own Duration — the phases already sum to it (see httpPhases),
// so the same value anchors both the bars and the numbers beside them.
func phaseLines(phases []netcheck.Phase, total time.Duration, width int) []string {
	lines := make([]string, 0, len(phases))
	for _, p := range phases {
		var pct float64
		if total > 0 {
			pct = float64(p.Duration) / float64(total) * 100
		}
		fill := theme.GaugeFillWidth(pct, theme.TimingBarWidth)
		bar := theme.TimingFillStyle().Render(theme.GaugeFill(fill)) +
			theme.GaugeTrackStyle().Render(theme.GaugeTrack(theme.TimingBarWidth-fill))
		label := theme.KeyStyle.Render(fmt.Sprintf("  %-*s", phaseLabelWidth, p.Name))
		pctText := theme.Bg(fmt.Sprintf(" %3.0f%%", pct))
		lines = append(lines, theme.PadWithBg(label+bar+pctText, width))
	}
	return lines
}

// section renders a titled block of prose, wrapped to the pane.
func section(width int, title, body string) []string {
	if strings.TrimSpace(body) == "" {
		return nil
	}
	lines := []string{
		theme.PadWithBg(theme.SubTitleStyle.Render(theme.IconConfig+" "+title), width),
		theme.EmptyLineBg(width),
	}
	wrapped := lipgloss.NewStyle().Width(max(width-4, 20)).Render(body)
	for line := range strings.SplitSeq(wrapped, "\n") {
		lines = append(lines, theme.PadWithBg(theme.Bg("  "+line), width))
	}
	lines = append(lines, theme.EmptyLineBg(width))
	return lines
}

// rebuildChecksTable refills the table from the filtered results.
func (m *Model) rebuildChecksTable() {
	m.checksTable.SetItems(m.visibleChecks())
	m.checksTable.Resize(m.width, max(m.height-13, 3))
}

func (m *Model) resizeInputs() {
	// Viewport border (2) + form padding (2) + prefix (2) + longest label "DNS Server " + chevron + spaces (~15)
	const labelOverhead = 21
	wide := max(m.width-labelOverhead, 20)
	m.targetInput.SetWidth(wide)
	m.dnsServerInput.SetWidth(wide)
	m.portInput.SetWidth(10)
}

func (m *Model) resizeDetailsViewport() {
	// Header ~9 lines + tab footer 3 lines + viewport border 2 lines = 14 overhead
	m.detailsViewport = viewport.New(viewport.WithWidth(max(m.width-4, 20)), viewport.WithHeight(max(m.height-13, 3)))
	m.detailsViewport.Style = lipgloss.NewStyle().Background(theme.ColorBackground)
}

// progressLabel names the question being asked, so a wait on a slow stage is
// legible rather than mute.
func (m *Model) progressLabel() string {
	return fmt.Sprintf("%s (%d/%d)", netcheck.StageTitle(m.runStage), m.runStep+1, m.totalSteps)
}

