314		}
315		var target bool
316		for _, h := range m.GetHeaderInfo("default") {
317			if h.Key == "Context" && h.Value != "default" {
318				t.Errorf("Context = %q, want the context passed in", h.Value)
319			}
320			target = target || (h.Key == "Target" && strings.Contains(h.Value, "example.com"))
321		}
