328		m := onPathTab(t)
329		before := testutil.ShortcutKeys(m.GetShortcuts())
330		m.pathModel.engine.supported = func() error { return nettrace.ErrUnsupported }
331		if !testutil.ShortcutDisabled(m.GetShortcuts(), "enter") {
332			t.Error("enter is not greyed out on an unsupported platform")
333		}
334		after := testutil.ShortcutKeys(m.GetShortcuts())
335		if strings.Join(before, ",") != strings.Join(after, ",") {
336			t.Errorf("the key set changed: %v -> %v", before, after)
337		}
338	}
339	
340	// ── Construction ─────────────────────────────────────────────────────────────
341	
342	// The resolve timeout is the config's check timeout, through checkSettings():
343	// the unit is seconds in the YAML and a zero is normalized, not a zero deadline.
344	func TestPathResolveTimeoutComesFromCheckSettings(t *testing.T) {
345		cfg := config.Default()
346		cfg.Network.CheckTimeout = 30
347		if got := New(cfg).pathModel.resolveTimeout; got != 30*time.Second {
348			t.Errorf("resolveTimeout = %v, want 30s", got)
349		}
350	
351		cfg.Network.CheckTimeout = 0
352		if got, want := New(cfg).pathModel.resolveTimeout, netcheck.DefaultCheckTimeout; got != want {
353			t.Errorf("a zeroed config gave resolveTimeout = %v, want the netcheck default %v", got, want)
354		}
355	}
