1	package netdiag
2	
3	import (
4		"fmt"
5		"strconv"
6		"time"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/nettrace"
11		"github.com/anthnel/devdesk/internal/ui/components"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/shortcut"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// pathBarLabel prefixes the target field in the bar.
18	const pathBarLabel = "Target › "
19	
20	// pathColumns describes the hops table. Plain text in Cell, colour in Style
21	// (Rule 122). A silent hop is dim, never red: it is not a failure.
22	func pathColumns() []datatable.Column[nettrace.Hop] {
23		hop := datatable.Column[nettrace.Hop]{
24			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
25			Cell: func(h nettrace.Hop) string { return strconv.Itoa(h.TTL) },
26		}
27		answer := datatable.Column[nettrace.Hop]{
28			Title: "Answer", Sizing: datatable.SizingFixed, MinWidth: 11,
29			Cell:  func(h nettrace.Hop) string { return h.Kind.String() },
30			Style: pathAnswerStyle,
31		}
32		address := datatable.Column[nettrace.Hop]{
33			Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
34			Cell: func(h nettrace.Hop) string {
35				if !h.Addr.IsValid() {
36					return "-"
37				}
38				return h.Addr.String()
39			},
40			Style: func(h nettrace.Hop) lipgloss.Style {
41				if !h.Addr.IsValid() {
42					return theme.DimStyle
43				}
44				return lipgloss.Style{}
45			},
46		}
47		rtt := datatable.Column[nettrace.Hop]{
48			Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
49			Cell: func(h nettrace.Hop) string {
50				if h.RTT <= 0 {
51					return "-"
52				}
53				return fmt.Sprintf("%.1f ms", float64(h.RTT)/float64(time.Millisecond))
54			},
55			Style: func(h nettrace.Hop) lipgloss.Style {
56				if h.RTT <= 0 {
57					return theme.DimStyle
58				}
59				return lipgloss.Style{}
60			},
61		}
62		return []datatable.Column[nettrace.Hop]{hop, answer, address, rtt}
63	}
64	
65	func pathAnswerStyle(h nettrace.Hop) lipgloss.Style {
66		switch h.Kind {
67		case nettrace.HopSilent, nettrace.HopUnresolved:
68			return theme.DimStyle
69		case nettrace.HopError:
70			return theme.SeverityTextStyle("MEDIUM")
71		}
72		return lipgloss.Style{}
73	}
74	
75	// view renders the table; the body is never replaced (Rule 139).
76	func (pm *PathModel) view() string { return pm.table.View() }
77	
78	// barView is the target field in its frame, two lines in every state.
79	func (pm *PathModel) barView(width int) string {
80		return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
81	}
82	
83	// statusLine is derived on every frame (Rule 128).
84	func (pm *PathModel) statusLine() components.Status {
85		if pm.errText != "" {
86			return components.Status{Text: pm.errText, Level: components.LevelError}
87		}
88		if pm.state != pathRunning {
89			return components.Status{}
90		}
91		host := pm.target.Host
92		n := len(pm.table.Items())
93		if !pm.addr.IsValid() && n == 0 {
94			return components.Status{Text: "Resolving " + host + "...", Activity: true}
95		}
96		where := host
97		if pm.addr.IsValid() && pm.addr.String() != host {
98			where += " (" + pm.addr.String() + ")"
99		}
100		noun := "hops"
101		if n == 1 {
102			noun = "hop"
103		}
104		return components.Status{
105			Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
106			Activity: true,
107		}
108	}
109	
110	// headerInfo lists the target and, once a run ended, how it ended.
111	func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
112		var out []shortcut.HeaderInfo
113		if pm.target.Host != "" {
114			value := pm.target.String()
115			if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
116				value += " (" + pm.addr.String() + ")"
117			}
118			out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
119		}
120		if pm.result != nil {
121			out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
122		}
123		return out
124	}
125	
126	// shortcuts: the running mode replaces the list, the other states grey out
127	// (Rule 130).
128	func (pm *PathModel) shortcuts() shortcut.Shortcuts {
129		off := !pm.launchable().Enabled()
130		switch pm.state {
131		case pathRunning:
132			return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
133		case pathDone:
134			return shortcut.Shortcuts{
135				{Key: "tab", Description: "Switch tab"},
136				{Key: "enter", Description: "Trace again", Disabled: off},
137				{Key: "esc", Description: "Edit the target"},
138				{Key: "?", Description: "Help"},
139			}
140		}
141		return shortcut.Shortcuts{
142			{Key: "tab", Description: "Switch tab"},
143			{Key: "enter", Description: "Trace the path", Disabled: off},
144		}
145	}
